script:
$d = $null
for ($t = 0; $t -lt 36; $t++) {
  $d = Get-PnpDevice -PresentOnly | Where-Object { $_.InstanceId -like 'SD\VID_02D0&PID_A9A6&FN_1*' } | Select-Object -First 1
  if ($d -and $d.Status -eq 'OK') { break }
  Start-Sleep -Seconds 5
}
if (-not $d) { 'FN_1 device not present after 3 min'; return }
Start-Sleep -Seconds 10    # let the boot-time probe (M3a) finish
$root = 'HKLM:\SYSTEM\CurrentControlSet\Enum\SD\VID_02D0&PID_A9A6&FN_1'
foreach ($i in Get-ChildItem $root) {
  $k = Join-Path $i.PSPath 'Device Parameters'
  if (-not (Test-Path $k)) { New-Item $k -Force | Out-Null }
  Set-ItemProperty $k -Name BootFw -Value 1 -Type DWord
  Set-ItemProperty $k -Name Ioctl -Value 1 -Type DWord
  Set-ItemProperty $k -Name ProbeState -Value 0 -Type DWord
  "armed BootFw+Ioctl: $($i.PSChildName)  Ver=" + (Get-ItemProperty $k).Ver
}
pnputil /restart-device $d.InstanceId | Out-String
